package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;

/**
 * Normalizes the telephone of a create-owner request to E.164 form: strips spaces, dashes and brackets,
 * keeps a leading '+' and country code when present, otherwise assumes country code '+61' and drops a
 * single leading '0' from the national digits, requiring 8 to 15 digits after the '+'. Anything that
 * cannot form a valid E.164 number is rejected with a 400 via {@link InvalidTelephoneException}. Mutates
 * the validated body in place (via {@code @Val}), so the stored and returned {@code telephone} is the
 * E.164 string (e.g. {@code 0412 345 678} becomes {@code +61412345678}). Runs after
 * {@link ValidateOwnerFields} (which guarantees a non-blank telephone) and before {@link BuildOwner}.
 */
public class NormalizeOwnerTelephone {

    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
        request.setTelephone(E164Telephone.normalize(request.getTelephone()));
    }
}
=== E164Telephone ===
package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;

/**
 * Converts a supplied telephone into E.164 form. Spaces, dashes and brackets are stripped; a leading
 * '+' with its country code is kept when present, otherwise country code '+61' is assumed and a single
 * leading '0' is dropped from the national digits. The result must carry 8 to 15 digits after the '+',
 * otherwise it cannot form a valid E.164 number and an {@link InvalidTelephoneException} (400) is thrown.
 */
final class E164Telephone {

    private E164Telephone() {
    }

    static String normalize(String telephone) throws InvalidTelephoneException {
        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()\\[\\]-]", "");
        boolean hasPlus = cleaned.startsWith("+");
        String rest = hasPlus ? cleaned.substring(1) : cleaned;
        if (rest.isEmpty() || !rest.chars().allMatch(Character::isDigit)) {
            throw new InvalidTelephoneException(telephone);
        }
        String digits;
        if (hasPlus) {
            digits = rest;
        }
        else {
            String national = rest.startsWith("0") ? rest.substring(1) : rest;
            digits = "61" + national;
        }
        if (digits.length() < 8 || digits.length() > 15) {
            throw new InvalidTelephoneException(telephone);
        }
        return "+" + digits;
    }
}
